import random

# Tạo một số ngẫu nhiên lớn hơn 1000
so_ngau_nhien = random.randint(1001, 999999)

# In số ngẫu nhiên
print(f"Số ngẫu nhiên: {so_ngau_nhien}")

# Hàm kiểm tra số nguyên tố
def la_so_nguyen_to(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

# Kiểm tra và in kết quả
if la_so_nguyen_to(so_ngau_nhien):
    print(f"{so_ngau_nhien} là số nguyên tố.")
else:
    print(f"{so_ngau_nhien} không phải là số nguyên tố.")
